-- FORGE Desktop exercise library: safe, repeatable starter seed.
-- Run only AFTER schema.sqlite.sql has initialized the database.
-- Existing users, exercises, and logged activity are not overwritten.
-- IMPORTANT: Desktop middleware currently looks up demo@forge.local.
-- This is an internal local account identifier, not a demo workout dataset.

BEGIN TRANSACTION;
INSERT OR IGNORE INTO users (email, password_hash) VALUES ('demo@forge.local', 'OFFLINE_DESKTOP_NO_LOGIN');

-- Generic profile for a new FORGE installation.
-- Users can personalize this later in Settings.
INSERT OR IGNORE INTO profiles (
    user_id,
    name,
    training_focus,
    height_cm,
    bio
)
SELECT
    id,
    'FORGE Athlete',
    NULL,
    NULL,
    NULL
FROM users
WHERE email = 'demo@forge.local';

